class InstantStatsStack<T extends Comparable<T>> {
    private static final int INITIAL_CAPACITY = 16;
    private T[] elements;
    private int size;

    // Track the maximum element seen *since the last pop of the current max*
    // This gives us O(1) queries for the "dominant" max in the active stack
    private T currentMax;
    private int currentMaxIndex;

    // The twist: we also track the "second-place" max so pops are smooth
    private T previousMax;
    private int previousMaxIndex;

    @SuppressWarnings("unchecked")
    public InstantStatsStack() {
        elements = new Comparable[INITIAL_CAPACITY];
        size = 0;
        currentMax = null;
        previousMax = null;
        currentMaxIndex = -1;
        previousMaxIndex = -1;
    }

    public void push(T value) {
        if (size == elements.length) {
            resize();
        }

        elements[size] = value;

        // Update max tracking
        if (currentMax == null || value.compareTo(currentMax) > 0) {
            previousMax = currentMax;
            previousMaxIndex = currentMaxIndex;
            currentMax = value;
            currentMaxIndex = size;
        } else if (previousMax == null || value.compareTo(previousMax) > 0) {
            previousMax = value;
            previousMaxIndex = size;
        }

        size++;
    }

    public T pop() {
        if (size == 0) {
            throw new EmptyStackException();
        }

        T value = (T) elements[--size];
        elements[size] = null; // Help GC

        // If we just popped the current max, demote the previous max
        if (currentMaxIndex == size) {
            currentMax = previousMax;
            currentMaxIndex = previousMaxIndex;
            previousMax = null;
            previousMaxIndex = -1;

            // Rescan for the new second-place max (only among remaining elements)
            if (size > 0) {
                for (int i = 0; i < size; i++) {
                    T elem = (T) elements[i];
                    if (elem != null && (previousMax == null || 
                        elem.compareTo(previousMax) > 0) && 
                        i != currentMaxIndex) {
                        previousMax = elem;
                        previousMaxIndex = i;
                    }
                }
            }
        } else if (previousMaxIndex == size) {
            // We popped the second-place max; find a new one
            previousMax = null;
            previousMaxIndex = -1;

            for (int i = 0; i < size; i++) {
                T elem = (T) elements[i];
                if (elem != null && i != currentMaxIndex &&
                    (previousMax == null || elem.compareTo(previousMax) > 0)) {
                    previousMax = elem;
                    previousMaxIndex = i;
                }
            }
        }

        return value;
    }

    /**
     * O(1) query: returns the current maximum in the stack.
     * The twist is that we maintain it eagerly, so you always know
     * the dominant element without scanning.
     */
    public T getMax() {
        if (size == 0) {
            throw new EmptyStackException();
        }
        return currentMax;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public int size() {
        return size;
